ext3_fsblk_t get_superblock_block(void **data, struct super_block *sb) {
    char *options = (char *)*data;
    ext3_fsblk_t block = 1;

    if (strncmp(options, "sb=", 3) == 0) {
        char *endptr;
        block = simple_strtoul(options + 3, &endptr, 0);
        if (endptr == options + 3) {
            return 1;
        }
        if (*endptr != '\0' && *endptr != ',') {
            printk(KERN_ERR "Invalid character in sb option: %s\n", options);
            return 1;
        }
        while (*endptr == ',') endptr++;
        *data = (void *)endptr;
    }
    return block;
}

ext3_fsblk_t get_superblock_block(void **data, struct super_block *sb) {
    char *options = (char *)(*data);
    ext3_fsblk_t block = 1;

    if (!options || memcmp(options, "sb=", 3) != 0) {
        return 1;
    }

    options += 3;
    char *end;
    block = simple_strtoul(options, &end, 0);
    if (options == end) {
        return 1;
    }

    if (*end != '\0' && *end != ',' && *end != ' ' && *end != '\t') {
        printk(KERN_ERR "Invalid characters after superblock block number.\n");
    }

    *data = (void *)end;
    return block;
}

